return $input.all().map((item) => {
  const j = item.json || {};
  const type = String(j.reminder_type || 'FOLLOW_UP').toUpperCase();
  const issueId = String(j.issue_uuid || '');
  const day = String(j.reminder_day || '');
  const now = new Date().toISOString();

  let prefix = 'Follow Up';

  if (type === 'DUE') prefix = 'Due';
  if (type === 'DECISION') prefix = 'Decision Due';

  const title = `${prefix}: ${j.title || 'Open Loop'}`;

  const parts = [];

  if (type === 'DECISION' && j.recommendation) {
    parts.push(`Recommend: ${j.recommendation}`);
  }

  if (type === 'DECISION' && j.decision_options) {
    const options = String(j.decision_options);
    parts.push(`Options: ${options.substring(0, 350)}`);
  }

  if (j.next_action) {
    parts.push(`Next: ${j.next_action}`);
  }

  if (j.waiting_on) {
    parts.push(`Waiting on: ${j.waiting_on}`);
  }

  if (j.assigned_to) {
    parts.push(`Owner: ${j.assigned_to}`);
  }

  if (!parts.length && j.description) {
    parts.push(String(j.description));
  }

  if (!parts.length) {
    parts.push('Open loop requires attention.');
  }

  const alert = {
    schema_version: '1.0',
    alert_id: `EXEC_ASSISTANT:${issueId}:${type}:${day}`,
    source: 'EXEC_ASSISTANT',
    source_event_id: `${issueId}:${type}:${day}`,
    category: 'EXECUTIVE',
    subtype: `OPEN_LOOP_${type}`,
    status: 'ACTIVE',
    event_action: 'REMINDER',
    title,
    message: parts.join(' · '),
    priority: Number(j.priority || 3),
    county: 'HUDSON',
    municipality: String(j.municipality || ''),
    location: {
      label: 'City Manager OS Command Center',
      address: '',
      state: 'NJ',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: [
      'executive-assistant',
      'open-loop',
      type.toLowerCase()
    ],
    click_url: 'http://100.94.203.47:8090/my-day',
    source_url: '',
    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,
    metadata: {
      issue_uuid: issueId,
      item_type: j.item_type || '',
      reminder_type: type,
      reminder_at: j.reminder_at || null,
      reminder_day: day
    }
  };

  alert.search_text = [
    alert.source,
    alert.category,
    alert.subtype,
    alert.title,
    alert.message,
    alert.municipality,
    ...alert.tags
  ].filter(Boolean).join(' ');

  return {json: alert};
});
